/**
 * Nav's browserslist shareable config: pinned minimum browser versions as
 * browserslist queries (e.g. `"chrome >= 108"`).
 *
 * Most consumers never import this directly — they reference it from
 * package.json instead:
 *
 * ```json
 * { "browserslist": ["extends @navikt/browserslist-config"] }
 * ```
 */
declare const queries: string[];
export default queries;
